for name, patch in PATCHES.items():
    p=Path(name); text=p.read_text()
    if hashlib.sha256(text.encode()).hexdigest()!=patch['sha']: raise ValueError('Base cambió: '+name)
    for a,b,value in reversed(patch['edits']): text=text[:a]+value+text[b:]
    p.write_text(text)
